import React, { useState } from 'react';  
import {  
  MdLock as Lock,  
  MdVisibility as Eye,  
  MdVisibilityOff as EyeOff,  
  MdClose as X  
} from 'react-icons/md';  
import { authService } from '../../services/authService';  
import './FirstLoginModal.css';  

const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000';  

const FirstLoginModal = ({ onPasswordChanged }) => {  
  const [loading, setLoading] = useState(false);  
  const [error, setError] = useState('');  
  const [passwordData, setPasswordData] = useState({  
    currentPassword: '',  
    newPassword: '',  
    confirmPassword: ''  
  });  
  const [showPasswords, setShowPasswords] = useState({  
    current: false,  
    new: false,  
    confirm: false  
  });  

  const handleInputChange = (field, value) => {  
    setPasswordData(prev => ({  
      ...prev,  
      [field]: value  
    }));  
  };  

  const togglePasswordVisibility = (field) => {  
    setShowPasswords(prev => ({  
      ...prev,  
      [field]: !prev[field]  
    }));  
  };  

  const handleSubmit = async (e) => {  
    e.preventDefault();  
    setError('');  

    // Validation  
    if (!passwordData.currentPassword || !passwordData.newPassword || !passwordData.confirmPassword) {  
      setError('Tous les champs sont requis');  
      return;  
    }  

    if (passwordData.newPassword !== passwordData.confirmPassword) {  
      setError('Les nouveaux mots de passe ne correspondent pas');  
      return;  
    }  

    if (passwordData.newPassword.length < 8) {  
      setError('Le nouveau mot de passe doit contenir au moins 8 caractères');  
      return;  
    }  

    try {  
      setLoading(true);  
      const token = authService.getToken();  
      const response = await fetch(`${API_BASE_URL}/api/users/first-login-password`, {  
        method: 'PUT',  
        headers: {  
          'Authorization': `Bearer ${token}`,  
          'Content-Type': 'application/json'  
        },  
        body: JSON.stringify({  
          currentPassword: passwordData.currentPassword,  
          newPassword: passwordData.newPassword  
        })  
      });  

      if (response.status === 401) {  
        authService.logout();  
        return;  
      }  

      const data = await response.json();  
      if (data.success) {  
        // Mettre à jour les données utilisateur pour supprimer le flag requiresPasswordChange  
        const currentUser = authService.getUser();  
        const updatedUser = { ...currentUser, requiresPasswordChange: false };  
        authService.setUser(updatedUser);  

        onPasswordChanged();  
      } else {  
        setError(data.message || 'Erreur lors du changement de mot de passe');  
      }  
    } catch (err) {  
      setError('Erreur de connexion');  
      console.error('Erreur:', err);  
    } finally {  
      setLoading(false);  
    }  
  };  

  return (  
    <div className="first-login-modal-overlay">  
      <div className="first-login-modal-content">  
        <div className="first-login-modal-header">  
          <div className="first-login-icon">  
            <Lock className="icon" />  
          </div>  
          <h2 className="first-login-title">Changement de mot de passe requis</h2>  
          <p className="first-login-subtitle">  
            Pour des raisons de sécurité, vous devez changer votre mot de passe temporaire  
          </p>  
        </div>  

        <form onSubmit={handleSubmit} className="first-login-form">  
          {error && (  
            <div className="alert alert-error">  
              {error}  
            </div>  
          )}  

          <div className="form-group">  
            <label className="form-label">Mot de passe actuel</label>  
            <div className="password-input-container">  
              <input  
                type={showPasswords.current ? 'text' : 'password'}  
                value={passwordData.currentPassword}  
                onChange={(e) => handleInputChange('currentPassword', e.target.value)}  
                className="form-input password-input"  
                placeholder="ChronoGaz2024"  
                required  
              />  
              <button  
                type="button"  
                className="password-toggle-btn"  
                onClick={() => togglePasswordVisibility('current')}  
              >  
                {showPasswords.current ? <EyeOff /> : <Eye />}  
              </button>  
            </div>  
          </div>  

          <div className="form-group">  
            <label className="form-label">Nouveau mot de passe</label>  
            <div className="password-input-container">  
              <input  
                type={showPasswords.new ? 'text' : 'password'}  
                value={passwordData.newPassword}  
                onChange={(e) => handleInputChange('newPassword', e.target.value)}  
                className="form-input password-input"  
                required  
                minLength="8"  
              />  
              <button  
                type="button"  
                className="password-toggle-btn"  
                onClick={() => togglePasswordVisibility('new')}  
              >  
                {showPasswords.new ? <EyeOff /> : <Eye />}  
              </button>  
            </div>  
            <small className="form-help">  
              Le mot de passe doit contenir au moins 8 caractères  
            </small>  
          </div>  

          <div className="form-group">  
            <label className="form-label">Confirmer le nouveau mot de passe</label>  
            <div className="password-input-container">  
              <input  
                type={showPasswords.confirm ? 'text' : 'password'}  
                value={passwordData.confirmPassword}  
                onChange={(e) => handleInputChange('confirmPassword', e.target.value)}  
                className="form-input password-input"  
                required  
              />  
              <button  
                type="button"  
                className="password-toggle-btn"  
                onClick={() => togglePasswordVisibility('confirm')}  
              >  
                {showPasswords.confirm ? <EyeOff /> : <Eye />}  
              </button>  
            </div>  
          </div>  

          <button  
            type="submit"  
            className="first-login-submit-btn"  
            disabled={loading}  
          >  
            {loading ? 'Changement en cours...' : 'Changer le mot de passe'}  
          </button>  
        </form>  
      </div>  
    </div>  
  );  
};  

export default FirstLoginModal;

import React, { useEffect, useState } from 'react';
import { Package, CheckCircle, Truck, XCircle, CheckSquare, CalendarClock } from 'lucide-react';
import axios from 'axios';

const StatisticsBar = ({ customerId }) => {
  const [stats, setStats] = useState({ 
    total: 0, 
    livree: 0,
    en_cours: 0,
    planifiee: 0,
    confirmee: 0,
    annulee: 0,
    totalPrix: 0
  });

  useEffect(() => {
    const fetchStats = async () => {
      try {
        const res = await axios.get(`http://localhost:5000/api/commands/customer/${customerId}/stats`);
        if (res.data.success) {
          const rawStats = res.data.data.repartitionParStatut;

          // Transformer le tableau en objet avec les bonnes clés
          const statusMap = {
            livree: 0,
            en_cours: 0,
            planifiee: 0,
            confirmee: 0,
            annulee: 0,
            totalPrix: res.data.data.chiffreAffaires || 0
          };

          rawStats.forEach(item => {
            const code = item.statut.code.toLowerCase(); // ex: "livree", "en_cours"
            if (statusMap.hasOwnProperty(code)) {
              statusMap[code] = item.count;
            }
          });

          // Calculer "en cours" comme la somme des statuts actifs
          statusMap.en_cours = (statusMap.planifiee || 0) + (statusMap.confirmee || 0);

          setStats(statusMap);
        }
      } catch (err) {
        console.error('Erreur lors de la récupération des stats:', err);
      }
    };

    if (customerId) {
      fetchStats();
    }
  }, [customerId]);

  return (
    <div className="bg-white rounded-lg shadow-md p-4 mb-6">
      <div className="flex justify-between items-center">
        <div className="flex items-center space-x-2">
          <CheckCircle size={20} className="text-green-500" />
          <span className="text-sm text-gray-600">Livrées:</span>
          <span className="text-lg font-bold text-green-600">{stats.livree || 0}</span>
        </div>

        <div className="flex items-center space-x-2">
          <Truck size={20} style={{color: '#4DAEBD'}} />
          <span className="text-sm text-gray-600">En cours:</span>
          <span className="text-lg font-bold" style={{color: '#4DAEBD'}}>{stats.en_cours || 0}</span>
        </div>

        <div className="flex items-center space-x-2">
          <CheckSquare size={20} className="text-blue-600" />
          <span className="text-sm text-gray-600">Confirmée:</span>
          <span className="text-lg font-bold" style={{color: '#4DAEBD'}}>{stats.confirmee || 0}</span>
        </div>

        <div className="flex items-center space-x-2">
          <CalendarClock size={20} className="text-blue-600" />
          <span className="text-sm text-perpule-600">Planifiée:</span>
          <span className="text-lg font-bold" style={{color: '#4DAEBD'}}>{stats.planifiee || 0}</span>
        </div>

        <div className="flex items-center space-x-2">
          <XCircle size={20} className="text-red-500" />
          <span className="text-sm text-gray-600">Annulées:</span>
          <span className="text-lg font-bold text-red-600">{stats.annulee || 0}</span>
        </div>

        <div className="flex items-center space-x-2">
          <Package size={20} style={{color: '#1F55A3'}} />
          <span className="text-sm text-gray-600">Total prix:</span>
          <span className="text-lg font-bold" style={{color: '#1F55A3'}}>
            {stats.totalPrix ? stats.totalPrix.toLocaleString() : 0} DH
          </span>
        </div>
      </div>
    </div>
  );
};

export default StatisticsBar;

// components/common/LoadingSpinner.js
import React from 'react';

const LoadingSpinner = ({ size = 'medium', text = '' }) => {
  const sizeClasses = {
    small: 'w-6 h-6 border-2',
    medium: 'w-8 h-8 border-3',
    large: 'w-12 h-12 border-4',
  }[size] || 'w-8 h-8 border-3';

  const textClass = {
    small: 'text-sm',
    medium: 'text-base',
    large: 'text-lg',
  }[size] || 'text-base';

  return (
    <div className="flex flex-col items-center justify-center space-y-2">
      <div
        className={`animate-spin rounded-full border-t-2 border-b-2 border-blue-500 ${sizeClasses}`}
      ></div>
      {text && <p className={`text-gray-500 font-medium ${textClass}`}>{text}</p>}
    </div>
  );
};

export default LoadingSpinner;

import React, { useState, useEffect } from 'react';          
import Title from '../../components/client/CommandPage/Title';          
import StepsIndicator from '../../components/client/CommandPage/StepsIndicator';          
import QuantityStep from '../../components/client/CommandPage/QuantityStep';          
import AddressStep from '../../components/client/CommandPage/AddressStep';          
import SummaryStep from '../../components/client/CommandPage/SummaryStep';          
import { authService } from '../../services/authService';        
import productService from '../../services/productService';        
import listePrixService from '../../services/listePrixService';        
import { createOrderFromSteps } from '../../services/orderService';        
import './Command.css'; 

const API_BASE_URL = process.env.REACT_APP_API_URL || 'http://localhost:5000';        

const Command = () => {        
  const [currentStep, setCurrentStep] = useState(1);        
  const [quantities, setQuantities] = useState({});        
  const [useGPS, setUseGPS] = useState(false);        

  // ✅ Structure d'adresse améliorée pour supporter les différents modes  
  const [address, setAddress] = useState({  
    use_existing_address: false,  
    address_id: null,  
    new_address: {  
      numappt: '',            
      numimmeuble: '',            
      street: '',            
      quartier: '',           
      city_id: '',          
      postal_code: '',            
      telephone: '',          
      instructions_livraison: '',  
      latitude: null,  
      longitude: null,  
      type_adresse: 'LIVRAISON'  
    },  
    existing_address_data: null  
  });         

  const [gpsLocation, setGpsLocation] = useState(null);        
  const [clientData, setClientData] = useState(null);        
  const [clientAddresses, setClientAddresses] = useState([]);        
  const [loadingClient, setLoadingClient] = useState(false);        

  const [selectedExistingAddress, setSelectedExistingAddress] = useState(null);      

  // États pour les produits depuis l'API        
  const [products, setProducts] = useState([]);        
  const [prices, setPrices] = useState({});        
  const [loading, setLoading] = useState(true);        
  const [error, setError] = useState(null);        

  const [cities, setCities] = useState([]);        
  const [loadingLocations, setLoadingLocations] = useState(false);        

  const deliveryFee = 20;        

  // Charger seulement les villes depuis l'API        
  const loadCities = async () => {        
    try {        
      setLoadingLocations(true);        
      const citiesResponse = await fetch(`${API_BASE_URL}/api/locations/cities`);        

      if (citiesResponse.ok) {        
        const citiesData = await citiesResponse.json();        
        setCities(citiesData.data || []);        
      }        
    } catch (error) {        
      console.error('Erreur lors du chargement des villes:', error);        
    } finally {        
      setLoadingLocations(false);        
    }        
  };        

  // Charger les produits et prix depuis l'architecture centralisée        
  const loadProductsWithPrices = async () => {          
    try {          
      setLoading(true);          

      // Charger les produits actifs        
      const productsResponse = await productService.getAllProducts({ actif: true }); 
      console.log('Réponse produits:', productsResponse); // Affichez la réponse de l'API


      if (productsResponse.success && productsResponse.data) {          
        const allProducts = productsResponse.data;          

        // Charger les prix depuis les listes de prix actives        
        try {        
          const pricesResponse = await listePrixService.getActivePrices();  
          console.log('Réponse prix:', pricesResponse); // Affichez la réponse de l'API

          const pricesMap = {};        
          const productsWithPrices = [];        

          if (pricesResponse.success && pricesResponse.data) {        
            // Créer un map des prix par product_id        
            pricesResponse.data.forEach(prixItem => {        
              pricesMap[prixItem.product_id] = prixItem.prix;        
            });        

            // Filtrer seulement les produits qui ont un prix défini        
            allProducts.forEach(product => {        
              if (pricesMap[product._id]) {        
                productsWithPrices.push(product);        
              }        
            });        
            console.log('Produits avec prix trouvés:', productsWithPrices);

            setProducts(productsWithPrices);        
            setPrices(pricesMap);        
          } else {        
            console.warn("Aucune liste de prix active trouvée");        
            setProducts([]);        
            setPrices({});        
          }        
        } catch (priceError) {        
          console.error("Erreur lors du chargement des prix:", priceError);        
          setProducts([]);        
          setPrices({});        
          setError("Impossible de charger les prix des produits");        
        }        
      }          
      setError(null);          
    } catch (err) {          
      console.error("Erreur lors du chargement des produits:", err);          
      setError("Erreur lors du chargement des produits");          
      setProducts([]);          
      setPrices({});          
    } finally {          
      setLoading(false);          
    }          
  };      

  // ✅ Amélioration du chargement des adresses client  
const loadClientData = async () => {          
  try {          
    setLoadingClient(true);          
    const user = authService.getUser();          
    if (user) {          
      setClientData(user);          

      // 🔧 CORRECTION: Récupérer customer_id comme dans le profil  
      let customerId = user.customer_id;  

      // Si pas de customer_id dans les données locales, le récupérer via l'API profile  
      if (!customerId) {  
        const token = authService.getToken();  
        const profileResponse = await fetch(`${API_BASE_URL}/api/users/profile`, {  
          headers: {  
            'Authorization': `Bearer ${token}`,  
            'Content-Type': 'application/json'  
          }  
        });  

        if (profileResponse.ok) {  
          const profileData = await profileResponse.json();  
          customerId = profileData.data?.customer_info?.customer_id;  

          // Mettre à jour les données utilisateur locales avec le customer_id  
          if (customerId && user) {  
            const updatedUser = { ...user, customer_id: customerId };  
            authService.setUser(updatedUser);  
            setClientData(updatedUser);  
          }  
        }  
      }  

      if (customerId) {        
        // Utiliser le nouveau endpoint du router modulaire    
        const addressesResponse = await fetch(`${API_BASE_URL}/api/customer/${customerId}/addresses`, {        
          headers: {        
            'Authorization': `Bearer ${authService.getToken()}`,        
            'Content-Type': 'application/json'        
          }        
        });          
        if (addressesResponse.ok) {          
          const addressesData = await addressesResponse.json();          
          setClientAddresses(addressesData.addresses || []);          
        } else {    
          console.warn('Impossible de charger les adresses client');    
          setClientAddresses([]);    
        }    
      }        
    }          
  } catch (error) {          
    console.error('Erreur lors du chargement des données client:', error);    
    setClientAddresses([]);          
  } finally {          
    setLoadingClient(false);          
  }          
};     

  useEffect(() => {          
    loadProductsWithPrices();      
    loadCities();          
    loadClientData();          
  }, []);       

  const handleQuantityChange = (productId, operation) => {        
    const product = products.find(p => p._id === productId);        
    if(!product) return;        

    if (operation === 'increment' && !product.actif){        
      alert('Impossible d\'ajouter un produit non disponible');        
      return;        
    }        
    setQuantities(prev => ({        
      ...prev,        
      [productId]: operation === 'increment'        
        ? (prev[productId] || 0) + 1        
        : Math.max(0, (prev[productId] || 0) - 1)        
    }));        
  };        

  const handleGPSLocation = () => {        
    if (navigator.geolocation) {        
      navigator.geolocation.getCurrentPosition(        
        (position) => {        
          setGpsLocation({        
            latitude: position.coords.latitude,        
            longitude: position.coords.longitude        
          });        
          setUseGPS(true);        
        },        
        (error) => {        
          console.error('Erreur géolocalisation:', error);  
          alert('Erreur lors de la géolocalisation');        
        }        
      );        
    } else {        
      alert('La géolocalisation n\'est pas supportée par ce navigateur');        
    }        
  };        

  const canProceedToStep2 = Object.values(quantities).some(qty => qty > 0);        

  // ✅ Validation améliorée pour tous les modes d'adresse  
  const canProceedToStep3 = () => {  
    if (useGPS && gpsLocation) {  
      return true;  
    }  

    if (selectedExistingAddress) {  
      return true;  
    }  

    if (address.use_existing_address && address.address_id) {  
      return true;  
    }  

    if (!address.use_existing_address && address.new_address) {  
      const newAddr = address.new_address;  
      return newAddr.street && newAddr.city_id && newAddr.telephone;  
    }  

    return false;  
  };  

  const subtotal = Object.entries(quantities).reduce((total, [productId, qty]) => {        
    return total + (qty * (prices[productId] || 0));        
  }, 0);        
  const total = subtotal + deliveryFee;        

  // ✅ Amélioration de la création de commande  
const handleConfirmOrder = async () => {            
  try {            
    const orderData = {            
      products,            
      quantities,            
      prices,            
      deliveryFee,            
      subtotal,            
      total,            
      useGPS,            
      gpsLocation,            
      selectedExistingAddress,          
      additionalInfo: '',      
      address: address    
    };            

    const result = await createOrderFromSteps(orderData);            
    console.log('✅ Commande créée avec succès:', result);            

    // 🔧 MODIFIÉ: Rediriger avec l'ID de la commande créée  
    if (result && result._id) {  
      window.location.href = `/TrackOrder/${result._id}`;  
    } else {  
      // Fallback si pas d'ID retourné  
      window.location.href = "/TrackOrder";  
    }           
  } catch (error) {            
    console.error('❌ Erreur création commande:', error);            
    alert(`Erreur lors de la création de la commande: ${error.message || 'Erreur inconnue'}`);            
  }            
};  

  const orderData = {        
    products,        
    quantities,        
    prices,        
    deliveryFee,        
    subtotal,        
    total,        
    useGPS,        
    address,        
    gpsLocation,      
    selectedExistingAddress      
  };        

  if (loading) {        
    return (        
      <div className="command-page-content">        
        <Title />        
        <div className="flex justify-center items-center h-64">        
          <div className="text-center">        
            <div className="animate-spin rounded-full h-12 w-12 border-b-2 border-blue-600 mx-auto"></div>        
            <p className="mt-4 text-gray-600">Chargement des produits...</p>        
          </div>        
        </div>        
      </div>        
    );        
  }        

  if (error) {        
    return (        
      <div className="command-page-content">        
        <Title />        
        <div className="flex justify-center items-center h-64">        
          <div className="text-center">        
            <p className="text-red-600 mb-4">{error}</p>        
            <button         
              onClick={loadProductsWithPrices}        
              className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700"        
            >        
              Réessayer        
            </button>        
          </div>        
        </div>        
      </div>        
    );        
  }        

  return (        
      <div className="command-wrapper">  
        <div className="command-container">  
          <div className="command-content">  
            <div className="command-page-content">  
              <Title />  
              <StepsIndicator currentStep={currentStep} />          
      <div className="max-w-4xl mx-auto p-6">          
        {currentStep === 1 && (        
          <QuantityStep        
            products={products}        
            quantities={quantities}        
            prices={prices}        
            onQuantityChange={handleQuantityChange}        
            onNext={() => setCurrentStep(2)}        
            canProceed={canProceedToStep2}      
            apiBaseUrl={API_BASE_URL}      
          />        
        )}        
        {currentStep === 2 && (        
          <AddressStep        
            useGPS={useGPS}        
            setUseGPS={setUseGPS}        
            address={address}        
            setAddress={setAddress}        
            gpsLocation={gpsLocation}        
            onGPSLocation={handleGPSLocation}        
            onBack={() => setCurrentStep(1)}        
            onNext={() => setCurrentStep(3)}        
            canProceed={canProceedToStep3()}        
            clientAddresses={clientAddresses}        
            loadingClient={loadingClient}        
            cities={cities}        
            loadingLocations={loadingLocations}      
            selectedExistingAddress={selectedExistingAddress}      
            setSelectedExistingAddress={setSelectedExistingAddress}      
          />        
        )}        
        {currentStep === 3 && (        
          <SummaryStep        
            orderData={orderData}        
            onBack={() => setCurrentStep(2)}        
            onConfirm={handleConfirmOrder}        
          />        
        )}        
      </div>          
       </div>  
      </div>  
    </div>  
  </div>          
  );        
};        

export default Command;

import React, { useState, useEffect, useCallback } from "react";  
import { useNavigate } from 'react-router-dom';  
import api from '../../services/api';  
import { authService } from '../../services/authService';  
import Title from "../../components/client/TrackOrderPage/Title";  
import OrderStatusCard from "../../components/client/TrackOrderPage/OrderStatusCard";  
import OrderSummary from "../../components/client/TrackOrderPage/OrderSummary";  
import { Package, Eye, Calendar, MapPin } from 'lucide-react';  
import './OrderHistory.css';  

const OrderHistory = () => {  
  const [orders, setOrders] = useState([]);  
  const [loading, setLoading] = useState(true);  
  const [error, setError] = useState(null);  
  const [selectedOrder, setSelectedOrder] = useState(null);  
  const [isDetailModalOpen, setIsDetailModalOpen] = useState(false);  
  const [searchTerm, setSearchTerm] = useState('');  
  const [filterStatus, setFilterStatus] = useState('all');  

  const navigate = useNavigate();  

  // Charger l'historique des commandes du client  
  const fetchOrderHistory = useCallback(async () => {    
    try {    
      setLoading(true);    
      setError(null);    

      const user = authService.getUser();    
      if (!user) {    
        navigate('/login');    
        return;    
      }    

      // Récupérer le customer_id depuis le profil utilisateur    
      let customerId = user?.customer_id;    

      // Si pas de customer_id dans les données locales, le récupérer via l'API profile    
      if (!customerId) {    
        const token = authService.getToken();    
        const profileResponse = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/users/profile`, {    
          headers: {    
            'Authorization': `Bearer ${token}`,    
            'Content-Type': 'application/json'    
          }    
        });    

        if (profileResponse.ok) {    
          const profileData = await profileResponse.json();    

          console.log("📊 Structure complète profileData:", profileData);    
          console.log("🏢 Type d'utilisateur:", profileData.data?.customer_info?.type_client);    

          // Chercher le Customer par user_id dans la liste des customers    
          if (profileData.data?.customer_info) {    
            const customerResponse = await fetch(`${process.env.REACT_APP_API_URL || 'http://localhost:5000'}/api/customers`, {    
              headers: {    
                'Authorization': `Bearer ${token}`,    
                'Content-Type': 'application/json'    
              }    
            });    

            if (customerResponse.ok) {    
              const customersData = await customerResponse.json();    
              console.log("📊 Données customers reçues:", customersData);    

              // Trouver le customer qui correspond à cet utilisateur    
              const customer = customersData.data?.find(c => {    
                // Pour les entreprises (MORAL)    
                if (c.type_client === 'MORAL' && c.user_info?.id === profileData.data.id) {    
                  return true;    
                }    
                // Pour les particuliers (PHYSIQUE)    
                if (c.type_client === 'PHYSIQUE' && c.user_info?.id === profileData.data.id) {    
                  return true;    
                }    
                return false;    
              });    

              if (customer) {    
                customerId = customer.id; // Utiliser customer.id    
                console.log("✅ Customer trouvé:", customer);    
              } else {    
                console.log("❌ Aucun customer trouvé pour l'utilisateur:", profileData.data.id);    
              }    
            }    
          }    

          console.log("🆔 Customer ID trouvé:", customerId);    

          // Mettre à jour les données utilisateur locales avec le customer_id    
          if (customerId && user) {    
            const updatedUser = { ...user, customer_id: customerId };    
            authService.setUser(updatedUser);    
          }    
        }    
      }    

      if (!customerId) {    
        setError('Informations client non disponibles. Veuillez contacter l\'administrateur.');    
        return;    
      }    

      // Utiliser l'endpoint existant qui fonctionne    
      const response = await api.get(`/commands/customer/${customerId}`);    
      console.log('Historique des commandes:', response.data);    

      if (response.data.success) {    
        setOrders(response.data.data || []);    
      } else {    
        setError('Erreur lors du chargement de l\'historique');    
      }    
    } catch (error) {    
      console.error('Erreur lors du chargement de l\'historique:', error);    
      setError('Erreur de connexion au serveur');    
    } finally {    
      setLoading(false);    
    }    
  }, [navigate]);  

  useEffect(() => {  
    fetchOrderHistory();  
  }, [fetchOrderHistory]);  

  // Fonction pour voir les détails d'une commande  
  const handleViewDetails = async (order) => {  
    try {  
      const orderResponse = await api.get(`/commands/${order._id || order.id}`);  

      if (orderResponse.data.success) {  
        setSelectedOrder(orderResponse.data.data);  
        setIsDetailModalOpen(true);  
      } else {  
        setError('Erreur lors du chargement des détails');  
      }  
    } catch (error) {  
      console.error('Erreur lors du chargement des détails:', error);  
      setError('Erreur lors du chargement des détails');  
    }  
  };  

  // Fonction pour obtenir le badge de statut  
  const getStatusBadge = (status) => {  
    const statusConfig = {  
      'NOUVELLE': { class: 'status-new', text: 'Nouvelle' },  
      'CONFIRMEE': { class: 'status-confirmed', text: 'Confirmée' },  
      'ASSIGNEE': { class: 'status-assigned', text: 'Assignée' },  
      'EN_COURS': { class: 'status-in-progress', text: 'En cours' },  
      'LIVREE': { class: 'status-delivered', text: 'Livrée' },  
      'ANNULEE': { class: 'status-cancelled', text: 'Annulée' },  
      'ECHOUEE': { class: 'status-failed', text: 'Échouée' }  
    };  

    const config = statusConfig[status] || { class: 'status-default', text: status };  
    return <span className={`status-badge ${config.class}`}>{config.text}</span>;  
  };  

  // Fonction pour formater la date  
  const formatDate = (dateString) => {  
    if (!dateString) return 'N/A';  
    return new Date(dateString).toLocaleDateString('fr-FR', {  
      day: '2-digit',  
      month: '2-digit',  
      year: 'numeric',  
      hour: '2-digit',  
      minute: '2-digit'  
    });  
  };  

  // Fonction pour obtenir la description du statut  
  const getStatusDescription = (order) => {  
    // ✅ Utiliser order.command.statut au lieu de order.statut  
    const status = order?.command?.statut;  

    if (status) {  
      switch(status) {  
        case 'CONFIRMEE': return "Commande confirmée avec succès";  
        case 'ASSIGNEE': return "Commande assignée à un livreur";  
        case 'EN_COURS': return "Livraison en cours";  
        case 'LIVREE': return "Commande livrée avec succès";  
        case 'ANNULEE': return "Commande annulée";  
        case 'ECHOUEE': return "Échec de la livraison";  
        default: return "Statut inconnu";  
      }  
    }  
    return "Statut non disponible";  
  };  

  // Filtrer les commandes (suppression de la recherche par numéro)  
  const filteredOrders = orders.filter(order => {  
    const matchesStatus = filterStatus === 'all' ||   
                         order.statut === filterStatus ||   
                         order.command?.statut === filterStatus;  

    return matchesStatus;  
  });  

  // Calculer les statistiques  
  const stats = {  
    total: orders.length,  
    delivered: orders.filter(order =>   
      order.statut === 'LIVREE' || order.command?.statut === 'LIVREE'  
    ).length,  
    inProgress: orders.filter(order =>   
      order.statut === 'EN_COURS' || order.command?.statut === 'EN_COURS'  
    ).length,  
    cancelled: orders.filter(order =>   
      order.statut === 'ANNULEE' || order.command?.statut === 'ANNULEE'  
    ).length  
  };  

  if (loading) {  
    return (  
      <div className="min-h-screen bg-gray-50 flex justify-center items-center">  
        <div className="text-center">  
          <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-blue-600 mx-auto mb-4"></div>  
          <div className="text-lg">Chargement de l'historique...</div>  
        </div>  
      </div>  
    );  
  }  

  if (error) {  
    return (  
      <div className="min-h-screen bg-gray-50 flex justify-center items-center">  
        <div className="text-center">  
          <div className="text-red-500 mb-4">  
            <Package className="w-16 h-16 mx-auto mb-4" />  
          </div>  
          <h3 className="text-xl font-bold text-gray-900 mb-2">Erreur de chargement</h3>  
          <p className="text-gray-600 mb-4">{error}</p>  
          <button   
            onClick={fetchOrderHistory}  
            className="bg-blue-600 hover:bg-blue-700 text-white px-4 py-2 rounded"  
          >  
            Réessayer  
          </button>  
        </div>  
      </div>  
    );  
  }  

  return (  
    <div className="order-wrapper">  
      <div className="order-container">  
        <div className="order-content">  
          <div className="order-page-content">  
            <div className="min-h-screen bg-gray-50">  
