const OrderDetailsModal = ({ order, onClose }) => {    
  const getStatusColor = (status) => {    
    const statusColors = {    
      pending: 'bg-yellow-100 text-yellow-800',    
      assigned: 'bg-blue-100 text-blue-800',    
      in_progress: 'bg-purple-100 text-purple-800',    
      delivered: 'bg-green-100 text-green-800',    
      cancelled: 'bg-red-100 text-red-800'    
    };    
    return statusColors[status] || 'bg-gray-100 text-gray-800';    
  };    

  const getStatusText = (status) => {    
    const statusTexts = {    
      pending: 'En attente',    
      assigned: 'Assignée',    
      in_progress: 'En cours',    
      delivered: 'Livrée',    
      cancelled: 'Annulée'    
    };    
    return statusTexts[status] || status;    
  };    

  const getPriorityColor = (priority) => {    
    const priorityColors = {    
      urgent: 'bg-red-100 text-red-800',    
      high: 'bg-orange-100 text-orange-800',    
      medium: 'bg-yellow-100 text-yellow-800',    
      low: 'bg-green-100 text-green-800'    
    };    
    return priorityColors[priority] || 'bg-gray-100 text-gray-800';    
  };    

  const getPriorityText = (priority) => {    
    const priorityTexts = {    
      urgent: 'Urgente',    
      high: 'Haute',    
      medium: 'Moyenne',    
      low: 'Basse'    
    };    
    return priorityTexts[priority] || priority;    
  };    

  const getPriorityIcon = (priority) => {  
    const icons = {  
      urgent: '🔴',  
      high: '🟠',   
      medium: '🟡',  
      low: '🟢'  
    };  
    return icons[priority] || '⚪';  
  };  

  // Calculer le total si pas disponible    
  const calculateTotal = () => {    
    if (order?.montant_total) return order.montant_total;    
    if (order?.total_ttc) return order.total_ttc;    

    if (order?.products && order.products.length > 0) {    
      return order.products.reduce((total, product) => {    
        const quantity = product.quantite || product.quantity || 0;    
        const price = product.prix_unitaire || product.price || 0;    
        return total + (quantity * price);    
      }, 0);    
    }    

    return 0;    
  };    

  const formatCurrency = (amount) => {    
    return new Intl.NumberFormat('fr-FR', {    
      style: 'currency',    
      currency: 'MAD',    
      minimumFractionDigits: 2    
    }).format(amount);    
  };    

