};    

const renderStars = (rating) => {    
  const stars = [];    
  const numRating = Number(rating) || 0;    
  for (let i = 1; i <= 5; i++) {    
    stars.push(    
      i <= numRating ?     
      <Star key={i} className="tracking-star-filled" /> :     
      <StarOff key={i} className="tracking-star-empty" />    
    );    
  }    
  return stars;    
};    

